<?php

declare(strict_types=1);
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>FourBag Player Account</title>
<style>
:root{--bg:#efe7d8;--paper:#fffaf0;--ink:#191714;--muted:#71685e;--red:#a43a2d;--green:#315844;--line:#d8ccb9;--shadow:0 12px 34px rgba(40,30,20,.1)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}.top{position:sticky;top:0;z-index:4;background:rgba(255,250,240,.95);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.topin{max-width:1180px;margin:auto;padding:15px 20px;display:flex;justify-content:space-between;gap:14px;align-items:center}.brand{font:800 26px Georgia,serif}.brand small{display:block;font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:.16em;color:var(--red);margin-top:3px}.wrap{max-width:1180px;margin:auto;padding:24px 20px 60px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:15px}.card{grid-column:span 12;background:var(--paper);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow);padding:18px}.s6{grid-column:span 6}.s7{grid-column:span 7}.s5{grid-column:span 5}h1,h2{font-family:Georgia,serif;margin:0 0 12px}h1{font-size:31px}h2{font-size:21px}h3{font-size:11px;text-transform:uppercase;letter-spacing:.11em;color:var(--green);margin:0 0 8px}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.split{display:flex;justify-content:space-between;gap:12px;align-items:center}.btn{border:1px solid var(--line);border-radius:9px;background:#fffdf8;color:var(--ink);padding:9px 12px;font-weight:800;cursor:pointer;text-decoration:none}.btn.green{background:var(--green);border-color:var(--green);color:#fff}.btn.red{background:var(--red);border-color:var(--red);color:#fff}input{border:1px solid #cdbfa9;border-radius:9px;background:#fffdf8;padding:10px;width:100%;font:inherit}.field{display:flex;flex-direction:column;gap:5px;margin-bottom:10px}.field label{font-size:11px;font-weight:800;color:var(--muted)}.muted{color:var(--muted)}.small{font-size:12px}.badge{display:inline-block;padding:5px 8px;border-radius:999px;background:#eee2cf;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.badge.green{background:#dfe9e1;color:#214331}.badge.red{background:#f2dedb;color:#7c291f}.notice{padding:12px;border:1px solid #dbc8ab;background:#efe3cf;border-radius:10px;font-size:12px;line-height:1.5}.error{background:#f4dfdc;border-color:#dfbdb7;color:#7b291f}.ok{background:#e3ebe4;border-color:#c6d7ca;color:#214331}.hidden{display:none!important}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.kpi{border:1px solid var(--line);border-radius:13px;background:#fffdf8;padding:13px}.kpi b{display:block;font:800 25px Georgia,serif}.kpi span{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-top:2px}.season{border:1px solid var(--line);border-radius:13px;background:#fffdf8;padding:14px;margin-bottom:9px}.season strong{font-family:Georgia,serif;font-size:17px}.meta{font-size:11px;color:var(--muted);margin-top:4px}.match{display:grid;grid-template-columns:70px 1fr 1fr 90px;gap:10px;align-items:center;border-bottom:1px solid #e7ddcd;padding:10px 0}.result{font:800 20px Georgia,serif}.result.W{color:var(--green)}.result.L{color:var(--red)}.empty{text-align:center;padding:26px;border:1px dashed #cdbfa9;border-radius:11px;color:var(--muted)}@media(max-width:900px){.s6,.s7,.s5{grid-column:span 12}.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.topin,.split{align-items:flex-start;flex-direction:column}.kpis{grid-template-columns:repeat(2,1fr)}.match{grid-template-columns:60px 1fr}.match>:nth-child(3),.match>:nth-child(4){grid-column:2}.wrap{padding-left:12px;padding-right:12px}}
</style>
</head>
<body>
<header class="top"><div class="topin"><div class="brand">FOURBAG<small>Player Account</small></div><div class="row"><a class="btn" href="./">League Network</a><div id="authBar"></div></div></div></header>
<main class="wrap"><div id="message" style="margin-bottom:12px"></div>
<div id="signedOut" class="grid">
<section class="card s6"><h3>Sign In</h3><h1>Your FourBag history.</h1><p class="muted">See your leagues, teams, match record, upcoming games, FourBag purchases, and championships in one place.</p><div class="field"><label>Email</label><input id="loginEmail" type="email" autocomplete="email"></div><div class="field"><label>Password</label><input id="loginPassword" type="password" autocomplete="current-password"></div><button class="btn green" id="login">Sign In</button></section>
<section class="card s6"><h3>New Player Account</h3><h2>Create an account before registering</h2><p class="small muted">When your account exists before your first league registration, FourBag securely links future league history to it automatically.</p><div class="field"><label>Name</label><input id="registerName" autocomplete="name"></div><div class="field"><label>Email</label><input id="registerEmail" type="email" autocomplete="email"></div><div class="field"><label>Password</label><input id="registerPassword" type="password" autocomplete="new-password" minlength="10"></div><button class="btn red" id="createAccount">Create Player Account</button></section>
</div>
<div id="app" class="grid hidden">
<section class="card"><div class="split"><div><h3>Player</h3><h1 id="playerName">FourBag Player</h1><div class="muted" id="playerEmail"></div></div><div class="row"><span class="badge green" id="linkStatus">Linked</span><button class="btn" id="refresh">Refresh</button></div></div></section>
<section class="card" id="statsCard"><div class="kpis"><div class="kpi"><b id="seasons">0</b><span>Seasons</span></div><div class="kpi"><b id="matches">0</b><span>Matches</span></div><div class="kpi"><b id="wins">0</b><span>Wins</span></div><div class="kpi"><b id="losses">0</b><span>Losses</span></div><div class="kpi"><b id="titles">0</b><span>Championships</span></div><div class="kpi"><b id="boards">0</b><span>FourBag Sets</span></div></div></section>
<section class="card s7"><h3>League History</h3><h2>Seasons + Teams</h2><div id="registrations"></div></section>
<section class="card s5"><h3>Next Up</h3><h2>Upcoming Matches</h2><div id="upcoming"></div></section>
<section class="card"><h3>Results</h3><h2>Recent Matches</h2><div id="results"></div></section>
</div>
</main>
<script>
const $=id=>document.getElementById(id);let currentUser=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function tell(text,type='ok'){$('message').innerHTML=text?`<div class="notice ${type}">${esc(text)}</div>`:''}
async function api(action,{method='GET',body=null,query={}}={}){const qs=new URLSearchParams({action,...query});const headers={'Accept':'application/json'};if(body)headers['Content-Type']='application/json';const r=await fetch(`api.php?${qs}`,{method,headers,credentials:'same-origin',body:body?JSON.stringify(body):null});const j=await r.json();if(!j.ok)throw new Error(j.error||'Request failed');return j.data}
function signedOut(){$('signedOut').classList.remove('hidden');$('app').classList.add('hidden');$('authBar').innerHTML=''}
function signedIn(){$('signedOut').classList.add('hidden');$('app').classList.remove('hidden');$('authBar').innerHTML=`<strong>${esc(currentUser.display_name)}</strong><button class="btn" id="logout">Sign Out</button>`;$('logout').onclick=logout}
async function authState(){try{const d=await api('auth.me');currentUser=d.user;if(currentUser){signedIn();await loadProfile()}else signedOut()}catch(e){signedOut();tell(e.message,'error')}}
async function login(){try{const d=await api('auth.login',{method:'POST',body:{email:$('loginEmail').value,password:$('loginPassword').value}});currentUser=d.user;signedIn();tell('Signed in.');await loadProfile()}catch(e){tell(e.message,'error')}}
async function createAccount(){try{const d=await api('auth.register',{method:'POST',body:{display_name:$('registerName').value,email:$('registerEmail').value,password:$('registerPassword').value}});currentUser=d.user;signedIn();tell('Player account created. Register for a league with this same email to link new history automatically.');await loadProfile()}catch(e){tell(e.message,'error')}}
async function logout(){await api('auth.logout',{method:'POST'});location.reload()}
function fmtDate(s){if(!s)return'—';const d=new Date(String(s).replace(' ','T'));return Number.isNaN(d.getTime())?s:d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function fmtWhen(s){if(!s)return'TBD';const d=new Date(String(s).replace(' ','T'));return Number.isNaN(d.getTime())?s:d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
async function loadProfile(){try{const d=await api('player.profile');$('playerName').textContent=d.player?.name||d.account.display_name;$('playerEmail').textContent=d.account.email;if(!d.linked){$('linkStatus').textContent='Account only';$('linkStatus').className='badge';$('statsCard').classList.add('hidden');$('registrations').innerHTML='<div class="notice"><strong>Your account is not linked to a player record yet.</strong><br>Register for a new league while signed in and use this account email to link new history. If you played before creating this account, FourBag administration can link prior history after identity verification.</div><div style="margin-top:10px"><a class="btn green" href="./#register">Register for a League</a></div>';$('upcoming').innerHTML='<div class="empty">No linked matches yet.</div>';$('results').innerHTML='<div class="empty">No linked results yet.</div>';tell('');return}
$('statsCard').classList.remove('hidden');$('linkStatus').textContent='History linked';$('linkStatus').className='badge green';$('seasons').textContent=d.stats.seasons;$('matches').textContent=d.stats.matches_played;$('wins').textContent=d.stats.wins;$('losses').textContent=d.stats.losses;$('titles').textContent=d.stats.championships;$('boards').textContent=d.stats.board_purchases;
$('registrations').innerHTML=d.registrations.length?d.registrations.map(r=>`<div class="season"><div class="split"><div><strong>${esc(r.season_name)}</strong><div class="meta">${esc(r.venue_name)}${r.city?', '+esc(r.city):''}${r.state?', '+esc(r.state):''} • starts ${esc(fmtDate(r.start_date))}</div></div><span class="badge ${r.season_status==='completed'?'green':''}">${esc(String(r.season_status).replaceAll('_',' '))}</span></div><div class="meta">Team: <b>${esc(r.team_name||'Unassigned')}</b> • ${esc(r.payment_status)}${Number(r.board_purchase)?' • FourBag set purchased':''}</div></div>`).join(''):'<div class="empty">No registrations yet.</div>';
$('upcoming').innerHTML=d.upcoming_matches.length?d.upcoming_matches.map(m=>`<div class="match"><span class="badge">W${Number(m.week_no)}</span><div><strong>vs ${esc(m.opponent)}</strong><div class="meta">${esc(m.venue_name)} • Board ${Number(m.board_no)}</div></div><div>${esc(fmtWhen(m.scheduled_at))}</div><span class="badge ${m.status==='live'?'red':''}">${esc(m.status)}</span></div>`).join(''):'<div class="empty">No scheduled matches.</div>';
$('results').innerHTML=d.recent_results.length?d.recent_results.map(m=>`<div class="match"><span class="result ${esc(m.result)}">${esc(m.result)}</span><div><strong>${esc(m.home_team)} ${Number(m.home_score)} — ${Number(m.away_score)} ${esc(m.away_team)}</strong><div class="meta">${esc(m.season_name)} • Week ${Number(m.week_no)} • Board ${Number(m.board_no)}</div></div><div>${esc(m.venue_name)}</div><span class="badge">${esc(m.stage)}</span></div>`).join(''):'<div class="empty">No final match results yet.</div>';tell('')}catch(e){tell(e.message,'error')}}
$('login').onclick=login;$('loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('createAccount').onclick=createAccount;$('registerPassword').addEventListener('keydown',e=>{if(e.key==='Enter')createAccount()});$('refresh').onclick=loadProfile;authState();
</script>
</body>
</html>
